import {zip} from './zip.js';
const $=id=>document.getElementById(id), items=[];let busy=false,activeCrop=null,cropImage=null,selection=null,dragStart=null;
const size=n=>n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(2)} MB`;
const notify=msg=>{$('notice').textContent=msg;$('notice').hidden=!msg;};
const image=url=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('이미지를 읽을 수 없습니다. 손상된 파일인지 확인하세요.'));im.src=url;});
function discard(item){if(item.result)URL.revokeObjectURL(item.result.url);item.result=null;item.error='';}
function invalidate(){for(const i of items)discard(i);$('zip').disabled=true;$('status').textContent='설정이 바뀌었습니다. 다시 처리해 주세요.';render();}
function downloadLink(result){const a=el('a','↓ 다운로드','download button');a.href=result.url;a.download=result.name;return a;}
function el(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;}
function button(text,fn,cls){const b=el('button',text,cls);b.onclick=fn;b.disabled=busy;return b;}
function render(){ $('editor').hidden=!items.length;$('dropzone').classList.toggle('compact',!!items.length);$('count').textContent=`${items.length}장`;$('cards').replaceChildren();
 for(const item of items){const card=el('article',null,'card');const title=el('div',null,'card-title');const info=el('div');info.append(el('h3',item.file.name),el('p',`${item.w} × ${item.h} · ${size(item.file.size)}`));title.append(info,button('✕',()=>{discard(item);URL.revokeObjectURL(item.url);items.splice(items.indexOf(item),1);render();$('zip').disabled=!items.some(i=>i.result);},'remove'));title.lastChild.setAttribute('aria-label',`${item.file.name} 제거`);card.append(title);
 const previews=el('div',null,'previews');for(const [label,url] of [['원본',item.url],['처리 결과',item.result?.url]]){const p=el('div',null,'preview'),box=el('div',null,'image-box');p.append(el('span',label));if(url){const im=el('img');im.src=url;im.alt=`${item.file.name} ${label}`;box.append(im);}else box.append(el('em','처리 후 여기에 표시됩니다'));p.append(box);previews.append(p);}card.append(previews);
 const tools=el('div',null,'tools');tools.append(button(item.crop?'자르기 수정':'자르기',()=>openCrop(item)),button('↻ 90°',()=>{item.rotation=(item.rotation+90)%360;discard(item);render();}),button('↔ 좌우',()=>{item.flipX=!item.flipX;discard(item);render();}),button('↕ 상하',()=>{item.flipY=!item.flipY;discard(item);render();}),button('편집 초기화',()=>{item.crop=null;item.rotation=0;item.flipX=false;item.flipY=false;discard(item);render();}));card.append(tools);
 card.append(el('p',`${item.crop?`자르기 ${item.crop.w} × ${item.crop.h} · `:''}회전 ${item.rotation}°${item.flipX?' · 좌우 반전':''}${item.flipY?' · 상하 반전':''}`,'hint'));
 if(item.error)card.append(el('p',item.error,'card-error'));
 if(item.result){const r=item.result,delta=(1-r.blob.size/item.file.size)*100;card.append(el('div',`${size(item.file.size)} → ${size(r.blob.size)} · ${Math.abs(delta).toFixed(1)}% ${delta>=0?'감소':'증가'} · ${r.w} × ${r.h}`,'result-meta'),downloadLink(r));} $('cards').append(card);
 }$('zip').disabled=busy||!items.some(i=>i.result);$('process').disabled=busy||!items.length;}
async function addFiles(files){if(busy)return;busy=true;render();const errors=[];let total=items.reduce((s,i)=>s+i.file.size,0);
 for(const file of files){if(items.length>=20){errors.push('한 번에 최대 20장까지 선택할 수 있습니다.');break;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){errors.push(`${file.name}: JPG, PNG, WebP 파일만 지원합니다.`);continue;}if(file.size>30*1048576||total+file.size>120*1048576){errors.push(`${file.name}: 파일당 30 MB, 전체 120 MB 이하로 선택해 주세요.`);continue;}const url=URL.createObjectURL(file);try{const im=await image(url);if(im.naturalWidth*im.naturalHeight>40000000)throw Error('최대 4천만 화소까지 지원합니다. 크기를 줄인 파일을 사용해 주세요.');items.push({file,url,w:im.naturalWidth,h:im.naturalHeight,crop:null,rotation:0,flipX:false,flipY:false,result:null});total+=file.size;}catch(e){URL.revokeObjectURL(url);errors.push(`${file.name}: ${e.message}`);}}
 busy=false;notify(errors.join('\n'));render();$('files').value='';}
function download(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function processItem(item,index){const im=await image(item.url),c=item.crop||{x:0,y:0,w:item.w,h:item.h};let rw=item.rotation%180?c.h:c.w,rh=item.rotation%180?c.w:c.h,w=rw,h=rh;
 if($('resize').checked){const tw=Number($('width').value),th=Number($('height').value);if(!Number.isInteger(tw)||!Number.isInteger(th)||tw<1||th<1||tw>12000||th>12000)throw Error('가로·세로에 1~12000 사이 정수를 입력해 주세요.');if($('lock').checked){const scale=Math.min(tw/rw,th/rh);w=Math.max(1,Math.round(rw*scale));h=Math.max(1,Math.round(rh*scale));}else{w=tw;h=th;}}
 if(w*h>40000000)throw Error('출력은 최대 4천만 화소까지 가능합니다.');const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');if(!ctx)throw Error('이 브라우저에서는 이미지 처리를 사용할 수 없습니다.');const mime=$('format').value;if(mime==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);}ctx.imageSmoothingQuality='high';ctx.translate(w/2,h/2);ctx.scale(w/rw,h/rh);ctx.scale(item.flipX?-1:1,item.flipY?-1:1);ctx.rotate(item.rotation*Math.PI/180);ctx.drawImage(im,c.x,c.y,c.w,c.h,-c.w/2,-c.h/2,c.w,c.h);
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,mime,Number($('quality').value)/100));canvas.width=canvas.height=1;if(!blob)throw Error('이미지를 만들지 못했습니다. 출력 크기를 줄여 다시 시도해 주세요.');if(blob.type!==mime)throw Error('이 브라우저는 선택한 출력 형식을 지원하지 않습니다. JPG 또는 PNG를 선택하세요.');const ext=mime.split('/')[1].replace('jpeg','jpg');const base=item.file.name.replace(/\.[^.]+$/,'').replace(/[\\/:*?"<>|]/g,'_');return {blob,url:URL.createObjectURL(blob),w,h,name:`${base}-flick-${index+1}.${ext}`};}
$('process').onclick=async()=>{if(busy)return;busy=true;notify('');$('progress').hidden=false;$('progress').max=items.length;$('progress').value=0;for(const i of items){discard(i);i.error='';}document.querySelectorAll('.settings input,.settings select,#choose,#add,#clear').forEach(e=>e.disabled=true);render();let ok=0;try{for(let n=0;n<items.length;n++){$('status').textContent=`${n+1} / ${items.length} 처리 중 · ${items[n].file.name}`;await new Promise(r=>setTimeout(r,20));try{items[n].result=await processItem(items[n],n);ok++;}catch(e){items[n].error=e.message;}$('progress').value=n+1;render();}}finally{busy=false;document.querySelectorAll('.settings input,.settings select,#choose,#add,#clear').forEach(e=>e.disabled=false);syncSettings();render();$('status').textContent=`처리 완료 · 성공 ${ok}장 / 실패 ${items.length-ok}장`;$('progress').hidden=true;}};
$('zip').onclick=async()=>{if(busy)return;busy=true;render();$('status').textContent='ZIP 파일을 만드는 중입니다…';try{const files=[];for(const i of items)if(i.result)files.push({name:i.result.name,data:new Uint8Array(await i.result.blob.arrayBuffer())});download(zip(files),'FLiCK-Photo.zip');$('status').textContent=`${files.length}장 ZIP 다운로드를 시작했습니다.`;}catch{$('status').textContent='ZIP 생성에 실패했습니다. 개별 다운로드를 이용해 주세요.';}finally{busy=false;render();}};
function syncSettings(){$('width').disabled=$('height').disabled=!$('resize').checked;const png=$('format').value==='image/png';$('quality').disabled=png;$('quality-value').textContent=`${$('quality').value}%`;$('format-note').textContent=png?'PNG는 무손실 형식으로 품질 슬라이더가 적용되지 않습니다. 크기 조절로 용량을 줄일 수 있으나 감소를 보장하지 않습니다.':$('format').value==='image/jpeg'?'JPG는 투명한 부분을 흰색으로 저장합니다.':'WebP는 투명 배경을 유지하며 품질을 조절할 수 있습니다.';}
for(const id of ['format','quality','resize','width','height','lock'])$(id).addEventListener('input',()=>{syncSettings();invalidate();});
for(const id of ['choose','add'])$(id).onclick=()=>$('files').click();$('files').onchange=e=>addFiles(e.target.files);$('clear').onclick=()=>{if(busy)return;for(const i of items){discard(i);URL.revokeObjectURL(i.url);}items.length=0;notify('');render();};
for(const type of ['dragenter','dragover'])$('dropzone').addEventListener(type,e=>{e.preventDefault();$('dropzone').classList.add('drag');});for(const type of ['dragleave','drop'])$('dropzone').addEventListener(type,e=>{e.preventDefault();$('dropzone').classList.remove('drag');if(type==='drop')addFiles(e.dataTransfer.files);});window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());
async function openCrop(item){activeCrop=item;cropImage=await image(item.url);selection={...(item.crop||{x:0,y:0,w:item.w,h:item.h})};$('crop-ratio').value='0';$('crop-error').textContent='';const canvas=$('crop-canvas');const scale=Math.min(900/item.w,600/item.h,1);canvas.width=Math.max(1,Math.round(item.w*scale));canvas.height=Math.max(1,Math.round(item.h*scale));$('crop-dialog').showModal();drawCrop();}
function drawCrop(){const canvas=$('crop-canvas'),ctx=canvas.getContext('2d'),s=canvas.width/activeCrop.w;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(cropImage,0,0,canvas.width,canvas.height);ctx.fillStyle='#10244788';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.save();ctx.beginPath();ctx.rect(selection.x*s,selection.y*s,selection.w*s,selection.h*s);ctx.clip();ctx.drawImage(cropImage,0,0,canvas.width,canvas.height);ctx.restore();ctx.strokeStyle='#60a5fa';ctx.lineWidth=2;ctx.strokeRect(selection.x*s,selection.y*s,selection.w*s,selection.h*s);for(const [id,key] of [['cx','x'],['cy','y'],['cw','w'],['ch','h']])$(id).value=selection[key];}
function point(e){const r=$('crop-canvas').getBoundingClientRect();return {x:Math.round(Math.max(0,Math.min(activeCrop.w,(e.clientX-r.left)/r.width*activeCrop.w))),y:Math.round(Math.max(0,Math.min(activeCrop.h,(e.clientY-r.top)/r.height*activeCrop.h)))};}
$('crop-canvas').onpointerdown=e=>{dragStart=point(e);e.target.setPointerCapture(e.pointerId);};$('crop-canvas').onpointermove=e=>{if(!dragStart)return;const p=point(e),ratio=Number($('crop-ratio').value);let w=Math.abs(p.x-dragStart.x),h=Math.abs(p.y-dragStart.y);if(ratio){w=Math.min(w,h*ratio);h=w/ratio;}selection={x:Math.round(p.x<dragStart.x?dragStart.x-w:dragStart.x),y:Math.round(p.y<dragStart.y?dragStart.y-h:dragStart.y),w:Math.max(1,Math.round(w)),h:Math.max(1,Math.round(h))};drawCrop();};$('crop-canvas').onpointerup=$('crop-canvas').onpointercancel=()=>dragStart=null;
function fitRatio(){const ratio=Number($('crop-ratio').value);if(ratio){const w=Math.min(selection.w,(activeCrop.h-selection.y)*ratio,activeCrop.w-selection.x);selection.w=Math.max(1,Math.floor(w));selection.h=Math.max(1,Math.round(selection.w/ratio));}drawCrop();}
$('crop-ratio').onchange=fitRatio;for(const [id,key] of [['cx','x'],['cy','y'],['cw','w'],['ch','h']])$(id).onchange=()=>{const v=Number($(id).value);selection[key]=Number.isFinite(v)?Math.round(v):0;if(key==='w'&&Number($('crop-ratio').value))selection.h=Math.round(selection.w/Number($('crop-ratio').value));if(key==='h'&&Number($('crop-ratio').value))selection.w=Math.round(selection.h*Number($('crop-ratio').value));drawCrop();};
$('crop-reset').onclick=()=>{selection={x:0,y:0,w:activeCrop.w,h:activeCrop.h};fitRatio();};$('crop-apply').onclick=()=>{const s=selection;if(s.x<0||s.y<0||s.w<1||s.h<1||s.x+s.w>activeCrop.w||s.y+s.h>activeCrop.h){$('crop-error').textContent='이미지 범위를 벗어났습니다. 원본 안의 좌표와 크기를 입력해 주세요.';return;}activeCrop.crop={...s};discard(activeCrop);$('crop-dialog').close();render();};syncSettings();
